targets.expr:
count by (failureCodeString) (count_over_time({eventType="Session",job=~"${KafkaJob}",siteName=~"${SiteName}",deliveryGroupName=~"${DeliveryGroup}"} 
| json failureCode = "failureCode", failureCodeString="failureCodeString" 
| failureCode != "" [5m]))

{eventType="Session",job=~"${KafkaJob}",siteName=~"${SiteName}",deliveryGroupName=~"${DeliveryGroup}"} 
| json failureCode = "failureCode", failureCodeString="failureCodeString", failureReasonString="failureReasonString", sessionKey="sessionKey"
| failureCode != ""

{eventType="Session",job=~"${KafkaJob}",siteName=~"${SiteName}",deliveryGroupName=~"${DeliveryGroup}"} 
| json failureCode = "failureCode", failureCodeString="failureCodeString", failureReasonString="failureReasonString", sessionKey="sessionKey"
| failureCode != ""

{eventType="Session",job=~"${KafkaJob}",siteName=~"${SiteName}",deliveryGroupName=~"${DeliveryGroup}"}
| json sessionKey = "sessionKey", logonDuration="logonDuration", sessionLaunchStatus = "sessionLaunchStatus"
| logonDuration != "" and sessionLaunchStatus = 0

{eventType="Session",job=~"${KafkaJob}",siteName=~"${SiteName}",deliveryGroupName=~"${DeliveryGroup}"}
| json sessionKey = "sessionKey", icaRtt="icaRtt", sessionLaunchStatus = "sessionLaunchStatus"
| icaRtt != "" and sessionLaunchStatus = 0
